"""Patch the Android project generated by `flutter create` for the Hoot app."""
import pathlib
import re

root = pathlib.Path(__file__).resolve().parent.parent / "android"

# 1) Manifest: permissions + Arabic app name
manifest = root / "app/src/main/AndroidManifest.xml"
m = manifest.read_text(encoding="utf-8")
perms = (
    '    <uses-permission android:name="android.permission.INTERNET"/>\n'
    '    <uses-permission android:name="android.permission.CAMERA"/>\n'
)
if "android.permission.INTERNET" not in m:
    m = m.replace("<application", perms + "    <application", 1)
m = re.sub(r'android:label="[^"]*"', 'android:label="Hoot drug store"', m, count=1)
manifest.write_text(m, encoding="utf-8")

# 2) Kotlin plugin version new enough for the camera/scanner plugins
for name in ("settings.gradle", "settings.gradle.kts"):
    f = root / name
    if f.exists():
        s = f.read_text(encoding="utf-8")
        s = re.sub(r'(org\.jetbrains\.kotlin\.android"\)?\s*version\s*")[0-9.]+(")', r"\g<1>1.9.24\2", s)
        # androidx.webkit needs AGP >= 8.1.1
        s = re.sub(r'(com\.android\.application"\)?\s*version\s*")[0-9.]+(")', r"\g<1>8.3.2\2", s)
        f.write_text(s, encoding="utf-8")

# AGP 8.3 needs Gradle 8.4+
wrapper = root / "gradle/wrapper/gradle-wrapper.properties"
if wrapper.exists():
    w = wrapper.read_text(encoding="utf-8")
    w = re.sub(r"gradle-[0-9.]+-(all|bin)\.zip", "gradle-8.7-all.zip", w)
    wrapper.write_text(w, encoding="utf-8")

# 3) minSdk 21 at least
for name in ("app/build.gradle", "app/build.gradle.kts"):
    f = root / name
    if f.exists():
        s = f.read_text(encoding="utf-8")
        s = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = 21", s)
        s = re.sub(r"minSdkVersion\s+flutter\.minSdkVersion", "minSdkVersion 21", s)
        f.write_text(s, encoding="utf-8")

print("android patched")
